    public partial class MainWindow
    {
        internal static string? GetBluetoothVersionViaApi()
        {
            IntPtr hFind = IntPtr.Zero, hRadio = IntPtr.Zero;
            try
            {
                var findParams = new BLUETOOTH_FIND_RADIO_PARAMS { dwSize = (uint)Marshal.SizeOf<BLUETOOTH_FIND_RADIO_PARAMS>() };
                hFind = BluetoothFindFirstRadio(ref findParams, out hRadio);
                if (hFind == IntPtr.Zero || hRadio == IntPtr.Zero) return null;

                var info = new BLUETOOTH_RADIO_INFO { dwSize = (uint)Marshal.SizeOf<BLUETOOTH_RADIO_INFO>() };
                int hr = BluetoothGetRadioInfo(hRadio, ref info);
                if (hr != 0) return null;

                return $"BT {LmpSubversionToBtVersion(info.lmpSubversion)}";
            }
            catch { return null; }
            finally
            {
                if (hRadio != IntPtr.Zero) CloseHandle(hRadio);
                if (hFind != IntPtr.Zero) BluetoothFindRadioClose(hFind);
            }
        }

        /// <summary>Official Bluetooth SIG table: lmpSubversion -> the public Core specification version. Ranges, not exact
        /// values, because individual subversions vary slightly between minor revisions of the same public version.</summary>
        private static string LmpSubversionToBtVersion(ushort lmp) => lmp switch
        {
            >= 15 => "5.3+",
            14    => "5.2",
            13    => "5.1",
            12    => "5.0",
            11    => "4.2",
            10    => "4.1",
            9     => "4.0",
            8     => "3.0",
            7     => "2.1",
            6     => "2.0",
            5     => "1.2",
            4     => "1.2",
            _     => "1.0b",
        };

        [StructLayout(LayoutKind.Sequential)]
        private struct BLUETOOTH_FIND_RADIO_PARAMS { public uint dwSize; }

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct BLUETOOTH_RADIO_INFO
        {
            public uint dwSize;
            public long address; // BLUETOOTH_ADDRESS union — 8 bytes, its content does not matter here
            [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 248)]
            public string szName;
            public uint ulClassofDevice;
            public ushort lmpSubversion;
            public ushort manufacturer;
        }

        [DllImport("BluetoothAPIs.dll", SetLastError = true)]
        private static extern IntPtr BluetoothFindFirstRadio(ref BLUETOOTH_FIND_RADIO_PARAMS pbtfrp, out IntPtr phRadio);

        [DllImport("BluetoothAPIs.dll")]
        private static extern int BluetoothGetRadioInfo(IntPtr hRadio, ref BLUETOOTH_RADIO_INFO pRadioInfo);

        [DllImport("BluetoothAPIs.dll")]
        private static extern bool BluetoothFindRadioClose(IntPtr hFind);

        [DllImport("kernel32.dll")]
        private static extern bool CloseHandle(IntPtr hObject);
    }
}
